// Shader variables
let theShader;
let shaderBg;

let moves = [0,0];
let time_;
let framerate;

async function setup() {

	theShader = await
  loadShader("https://openprocessing.org/sketch/2715765/files/vertex.vert", "fragment.frag");

	createCanvas(windowWidth, windowHeight);
	 // disables scaling for retina screens which can create inconsistent scaling between displays
  pixelDensity(1);
  noStroke();

  // shaders require WEBGL mode to work
  shaderBg = createGraphics(windowWidth, windowHeight, WEBGL);
	cursor('grab');

	describe('Escher infinite bended frame Inspired by Escher-s Cubic Space Division (1952)');
}

function draw() {
  // we can draw the background each frame or not.
  // if we do we can use transparency in our shader.
  // if we don't it will leave a trailing after image.
  // background(0);
  // shader() sets the active shader with our shader
  shaderBg.shader(theShader);

  // get the mouse coordinates, map them to values between 0-1 space
  let yMouse = (map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, height, 0) / height) * 2 - 1;
  let xMouse = ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) / width) * 2 - 1;

  // Make sure pixels are square
  xMouse = (xMouse * width) / height;
  yMouse = yMouse;

	mouseMove();
  // pass the interactive information to the shader
  theShader.setUniform("iResolution", [width, height]);
  theShader.setUniform("iTime", millis() / 1000.0);
  theShader.setUniform("iMouse", moves);

  // rect gives us some geometry on the screen to draw the shader on
  shaderBg.rect(0, 0, width, height);
  image(shaderBg, 0, 0, width, height);

	let increment = 20 / ((frameRate() || 60) * 140); // timestep based on framerate, will rotate same speed on all regardless of framerate
  time_ += increment;
  if(time_ > TWO_PI) time_ -= TWO_PI; // prevent time from getting to big and maybe causing errors?

}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
	theShader.setUniform("iResolution", [width, height]);
}

function mousePressed() {
  cursor('grabbing');
}

function mouseReleased() {
  cursor('grab');
}

function mouseMove() {
	if (!((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))) return;
	moves[0] += (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)));
	moves[1] += (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)));
}

// === Tab: vertex.vert ===
// These are necessary definitions that let you graphics card know how to render the shader
#ifdef GL_ES
precision highp float;
#endif

// Vertex attributes
attribute vec3 aPosition;
attribute vec2 aTexCoord;

// Pass-through to the fragment shader
varying vec2 vTexCoord;

void main() {
    // Pass texture coordinates to the fragment shader
    vTexCoord = aTexCoord;

    // Transform the position into normalized device coordinates (NDC)
    vec4 positionVec4 = vec4(aPosition, 1.0);

    // Scale and shift to NDC (Normalize Device Coordinate) range [-1, 1]
    positionVec4.xy = positionVec4.xy * 2.0 - 1.0;

    // Set the final position of the vertex
    gl_Position = positionVec4;
}


// === Tab: fragment.frag ===
/*
 You can use this as a template to make shaders! Have fun!

 Escher infinite bended frame
 Juan Carlos Ponce Campuzano
 28/Aug/2025
 https://www.patreon.com/jcponce

 Inspired by Escher's Cubic Space Division (1952)
 https://escherinhetpaleis.nl/en/about-escher/escher-today/cubic-space-division

*/

// These are necessary definitions that let your graphics card know how to render the shader
#ifdef GL_ES
precision highp float;
#endif

// These are our passed in information from the sketch.js
uniform vec2 iResolution;
uniform float iTime;
uniform vec2 iMouse;

#define PI 3.14159265359

varying vec2 vTexCoord;

// 2D rotation function
mat2 rot2D(float a) {
    return mat2(cos(a), -sin(a), sin(a), cos(a));
}

// Box
float sdBox( vec3 p, vec3 b )
{
  vec3 q = abs(p) - b;
  return length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0);
}

//https://iquilezles.org/articles/palettes/
vec3 palette1( float t ) {
    vec3 a = vec3(0.0, 0.5, 0.5);
    vec3 b = vec3(0.0, 0.5, 0.5);
    vec3 c = vec3(0.0, 0.5, 0.333);
    vec3 d = vec3(0.0, 0.5, 0.667);

    return a + b*cos( 6.28318*(c*t+d) );
}

vec3 palette2( float t ) {
    vec3 a = vec3(0.939, 0.328, 0.718);
    vec3 b = vec3(0.659, 0.438, 0.328);
    vec3 c = vec3(0.388, 0.388, 0.296);
    vec3 d = vec3(2.538, 29.478, 0.168);

    return a + b*cos( 6.28318*(c*t+d) );
}

float easingFunction( float t){
		return 0.5 * cos(t * 0.4 + PI) + 0.5;
}

// Scene distance
float map(vec3 p) {
    p.z += iTime * 0.3;

    vec3 q = p;

    q = fract(p) - 0.5;

		float verBeam = sdBox(q, vec3(0.03, 0.5, 0.03));
		float horBeam = sdBox(q, vec3(0.5, 0.05, 0.03));
		float zBeam = sdBox(q, vec3(0.03, 0.03, 0.5));
		float centralCube = sdBox(q, vec3(0.15, 0.15, 0.15));

    return min( centralCube, min(verBeam, min(horBeam, zBeam)) ); // distance to an object
		//return sdBoxFrame( q, vec3(30.5), 0.01 );
}

void main() {
    // copy the vTexCoord
    // vTexCoord is a value that goes from 0.0 - 1.0 depending on the pixels location
    // we can use it to access every pixel on the screen

    vec2 coord = vTexCoord;

    vec2 uv = ( coord * 2.0 - 1.2 ) * iResolution.xy / iResolution.y;

    vec3 ro = vec3(0.0, 0.0, -3.0); // ray origin
    vec3 rd = normalize(vec3(uv, 1.0)); // ray direction
    vec3 col = vec3(0.0); // final pixel color

    float t = 0.0; // total distance travelled

		// Updated thanks to Matthias Hurrle from this sketch
		// https://openprocessing.org/sketch/2679978
		float MN = min(iResolution.x,iResolution.y);
    // Horizontal camera rotation
    ro.yz *= rot2D(-iMouse.y*6.3/MN);
    rd.yz *= rot2D(-iMouse.y*6.3/MN);

    // Horizontal camera rotation
    ro.xz *= rot2D(-iMouse.x*6.3/MN);
    rd.xz *= rot2D(-iMouse.x*6.3/MN);

		// 👇 transition control Auxilary function
    // float u = smoothstep(0.0, 31.0, 0.5 + 0.5*sin(iTime*0.5));
    // float u = smoothstep(0.0, 5.0, iTime); // alternative: one-way morph

    // Raymarching

    for(int i = 0; i < 58; i++){
      vec3 p = ro + rd * t; // position along the ray

			p.zy *= rot2D(-0.3);
			p.zx *= rot2D(-0.4);

			p.xy *= rot2D(t*30.045);  // rotate ray around z-axis

			p.y += sin(t*0.5)*0.35; // wiggle ray along y-axis

      float d = map(p);

      t += d;

      if (d < 0.001 || t > 100.0) break; // "d" early stop if close enough
																				 // "t" early stop if too far
    }

    // Coloring
		float u = smoothstep(0.0, 16.0, 0.5 + 0.5*sin(iTime*0.5));
		vec3 p1 = palette1(t*0.1 + 0.01);
		vec3 p2 = palette2(t*0.1 + 0.01);
		col = mix(p2, p1, u);

		// float transForm = easingFunction(iTime);
		// col = palette2(t*0.1 + 0.01) * transForm + palette1(t*0.1 + 0.01) * (1.0 - transForm); // Alternatively


    // gl_FragColor is a built in shader variable, and 
		// your .frag file must contain it
    // We are setting the vec3 color into a new vec4, 
		// with a transparency of 1 (no opacity)
	  gl_FragColor = vec4(col, 1.0);
}

